ALTER TABLE public.account_preferences ADD COLUMN content_categories text[];
UPDATE public.account_preferences SET content_categories=CASE WHEN customer_preference='both' THEN ARRAY['women','men'] WHEN customer_preference IS NOT NULL THEN ARRAY[customer_preference] ELSE NULL END;
ALTER TABLE public.account_preferences ADD CONSTRAINT content_categories_valid CHECK(content_categories IS NULL OR (content_categories <@ ARRAY['women','men','trans_women','trans_men']::text[] AND array_position(content_categories,NULL) IS NULL));
ALTER TABLE public.profiles ADD COLUMN content_labels text[];
ALTER TABLE public.profiles ADD CONSTRAINT content_labels_valid CHECK(content_labels IS NULL OR (cardinality(content_labels)>0 AND content_labels <@ ARRAY['dance','twerking','fitness','cosplay','solo','multiple-performers','non-explicit','penis-visible','vulva-visible','no-genitals-visible']::text[] AND array_position(content_labels,NULL) IS NULL));
CREATE FUNCTION public.save_my_content_preferences(_categories text[]) RETURNS text[] LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result text[]; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF _categories IS NULL OR NOT (_categories <@ ARRAY['women','men','trans_women','trans_men']::text[]) OR array_position(_categories,NULL) IS NOT NULL THEN RAISE EXCEPTION 'INVALID_CATEGORIES'; END IF; SELECT COALESCE(array_agg(DISTINCT c ORDER BY c),'{}') INTO result FROM unnest(_categories)c; UPDATE public.account_preferences SET content_categories=result,updated_at=now() WHERE user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'ACCOUNT_PREFERENCES_REQUIRED'; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.save_my_content_preferences(text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_my_content_preferences(text[]) TO authenticated,service_role;
CREATE FUNCTION public.save_my_creator_discovery(_category text,_labels text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'creator') THEN RAISE EXCEPTION 'CREATOR_REQUIRED'; END IF; IF _category IS NULL OR _category NOT IN ('women','men','trans_women','trans_men') THEN RAISE EXCEPTION 'PROFILE_CATEGORY_REQUIRED'; END IF; IF _labels IS NULL OR cardinality(_labels)=0 OR NOT (_labels <@ ARRAY['dance','twerking','fitness','cosplay','solo','multiple-performers','non-explicit','penis-visible','vulva-visible','no-genitals-visible']::text[]) OR array_position(_labels,NULL) IS NOT NULL THEN RAISE EXCEPTION 'CONTENT_LABELS_REQUIRED'; END IF; UPDATE public.profiles SET vault_side=_category,content_labels=_labels,tags=ARRAY(SELECT DISTINCT t FROM unnest(COALESCE(tags,'{}'))t WHERE t NOT IN ('dance','twerking','fitness','cosplay','solo','multiple-performers','non-explicit','penis-visible','vulva-visible','no-genitals-visible'))||_labels,updated_at=now() WHERE user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; END $$;
REVOKE ALL ON FUNCTION public.save_my_creator_discovery(text,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_my_creator_discovery(text,text[]) TO authenticated,service_role;
CREATE FUNCTION public.search_creator_categories(_query text,_categories text[],_countries text[] DEFAULT '{}',_offset integer DEFAULT 0) RETURNS SETOF public.public_profiles LANGUAGE sql STABLE SET search_path=public AS $$ SELECT p.* FROM public.public_profiles p WHERE p.role='creator' AND p.vault_side=ANY(_categories) AND (p.display_name ILIKE '%'||left(_query,100)||'%' OR p.country=ANY(_countries) OR EXISTS(SELECT 1 FROM unnest(p.tags)t WHERE t ILIKE '%'||left(_query,100)||'%')) ORDER BY (public.get_creator_vip_status(p.user_id)->>'priority_active')::boolean DESC,p.user_id LIMIT 25 OFFSET GREATEST(0,_offset) $$;
REVOKE ALL ON FUNCTION public.search_creator_categories(text,text[],text[],integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.search_creator_categories(text,text[],text[],integer) TO authenticated,service_role;
CREATE FUNCTION public.get_teaser_categories(_categories text[],_country text DEFAULT NULL,_query text DEFAULT '',_offset integer DEFAULT 0) RETURNS SETOF public.creator_media LANGUAGE sql STABLE SET search_path=public AS $$ SELECT m.* FROM public.get_active_teasers()m JOIN public.public_profiles p ON p.user_id=m.creator_id LEFT JOIN public.creator_heart_totals h ON h.creator_id=m.creator_id WHERE p.vault_side=ANY(_categories) AND (_country IS NULL OR _country='GLOBAL' OR p.country=_country) AND (COALESCE(_query,'')='' OR p.display_name ILIKE '%'||left(_query,100)||'%' OR m.title ILIKE '%'||left(_query,100)||'%' OR EXISTS(SELECT 1 FROM unnest(p.tags)t WHERE t ILIKE '%'||left(_query,100)||'%')) ORDER BY (public.get_creator_vip_status(m.creator_id)->>'priority_active')::boolean DESC,COALESCE(h.hearts,0) DESC,m.creator_id LIMIT 24 OFFSET GREATEST(0,_offset) $$;
REVOKE ALL ON FUNCTION public.get_teaser_categories(text[],text,text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_teaser_categories(text[],text,text,integer) TO authenticated,service_role;